// Copyright 2015-2021 Crytek GmbH / Crytek Group. All rights reserved.#include "StdAfx.h"#include "Bloom.h"#include "D3DPostProcess.h"// Taps per stretch iteration. Must match the unrolled loop in HDRStreakStretchPS.static const int s_nStreakTapCount = 8;// Per tap intensity falloff of the first iteration. Later iterations raise it by the tap// count so the combined falloff stays exponential in distance rather than in iteration.static const float s_fStreakDecay = 0.93f;void CBloomStage::Execute(){	FUNCTION_PROFILER_RENDERER();	// Approximate function (1 - r)^4 by a sum of Gaussians: 0.0174*G(0.008,r) + 0.192*G(0.0576,r)	const float sigma1 = sqrtf(0.008f);	const float sigma2 = sqrtf(0.0576f - 0.008f);	PROFILE_LABEL_SCOPE("BLOOM_GEN");	static CCryNameTSCRC techBloomGaussian("HDRBloomGaussian");	static CCryNameR hdrParams0Name("HDRParams0");	int width = m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth();	int height = m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetHeight();	// Note: Just scaling the sampling offsets depending on the resolution is not very accurate but works acceptably#if defined(USE_CRY_ASSERT)	int widthHalfRes = (m_graphicsPipelineResources.m_pTexHDRTarget->GetWidth() + 1) / 2;	int widthQuarterRes = (widthHalfRes + 1) / 2;	CRY_ASSERT(m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth() == widthQuarterRes);#endif	float scaleW = ((float)width / 400.0f) / (float)width;	float scaleH = ((float)height / 225.0f) / (float)height;	// TODO: Compute shader! because the targets are not compressed / able anyway, and we can half resource allocation)	SamplerStateHandle samplerBloom = (m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetWidth() == 400 && m_graphicsPipelineResources.m_pTexHDRFinalBloom->GetHeight() == 225) ? EDefaultSamplerStates::PointClamp : EDefaultSamplerStates::LinearClamp;	// Pass 1 Horizontal	if (m_pass1H.IsDirty())	{		m_pass1H.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass1H.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass1H.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass1H.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass1H.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass1H.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass1H.SetSampler(0, samplerBloom);	}	m_pass1H.BeginConstantUpdate();	m_pass1H.SetConstant(hdrParams0Name, Vec4(scaleW, 0, 0, 0), eHWSC_Pixel);	m_pass1H.Execute();	// Pass 1 Vertical	if (m_pass1V.IsDirty())	{		m_pass1V.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass1V.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass1V.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass1V.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass1V.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass1V.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass1V.SetSampler(0, samplerBloom);	}	m_pass1V.BeginConstantUpdate();	m_pass1V.SetConstant(hdrParams0Name, Vec4(0, scaleH, 0, 0), eHWSC_Pixel);	m_pass1V.Execute();	// Pass 2 Horizontal	if (m_pass2H.IsDirty())	{		m_pass2H.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass2H.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass2H.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, 0);		m_pass2H.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass2H.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass2H.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass2H.SetSampler(0, samplerBloom);	}	m_pass2H.BeginConstantUpdate();	m_pass2H.SetConstant(hdrParams0Name, Vec4((sigma2 / sigma1) * scaleW, 0, 0, 0), eHWSC_Pixel);	m_pass2H.Execute();	// Pass 2 Vertical	if (m_pass2V.IsDirty())	{		m_pass2V.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_pass2V.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_pass2V.SetTechnique(CShaderMan::s_shHDRPostProcess, techBloomGaussian, g_HWSR_MaskBit[HWSR_SAMPLE0]);		m_pass2V.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRFinalBloom);		m_pass2V.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_pass2V.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1]);		m_pass2V.SetTexture(1, m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0]);		m_pass2V.SetSampler(0, samplerBloom);	}	m_pass2V.BeginConstantUpdate();	m_pass2V.SetConstant(hdrParams0Name, Vec4(0, (sigma2 / sigma1) * scaleH, 0, 0), eHWSC_Pixel);	m_pass2V.Execute();	ExecuteStreaks();	ExecuteFilterPSF();	ExecuteHalation();}// Aperture diffraction streaks (sunstars).//// Runs after the bloom chain, which leaves both quarter resolution HDR scratch targets free:// $HDRTarget 1/4b holds the thresholded sources and $HDRTarget 1/4a is the ping-pong buffer,// so the streaks cost no permanent memory of their own. The half resolution HDR scene is// still intact at this point (the sun shafts stage reads it afterwards) and serves as the// threshold input. The last stretch iteration blends straight into $HDRFinalBloom, so the// streaks travel through the existing bloom composition instead of a second tone-map hook.void CBloomStage::ExecuteStreaks(){	if (!CRenderer::CV_r_HDRStreaks)		return;	CHDRStreaks* pStreaksTech = static_cast<CHDRStreaks*>(PostEffectMgr()->GetEffect(EPostEffectID::HDRStreaks));	if (pStreaksTech == nullptr)		return;	SHDRStreaksParams streakParams = pStreaksTech->GetParams();	// r_HDRStreaks 2: diagnostic force mode - full strength, low threshold, eight spikes,	// independent of any game code driving the params.	if (CRenderer::CV_r_HDRStreaks == 2)	{		streakParams.bActive = true;		streakParams.fAmount = 1.0f;		streakParams.nDirectionCount = 8;		streakParams.fAngle = 0.4f;		streakParams.fThreshold = 0.5f;		streakParams.fLength = 0.6f;	}	// Two independent effects share this pass block: the iris diffraction spikes and the	// anamorphic horizontal flare thrown by a cylindrical front element. Either one alone is	// enough to run the block; only both being off skips it.	const bool bBlade = streakParams.bActive && streakParams.fAmount >= 0.001f && streakParams.nDirectionCount >= 4;	const bool bAnamorphic = streakParams.fAnamorphicAmount >= 0.001f;	if (!bBlade && !bAnamorphic)		return;	PROFILE_LABEL_SCOPE("HDR_STREAKS");	static CCryNameTSCRC techStreakThreshold("HDRStreakThreshold");	static CCryNameTSCRC techStreakStretch("HDRStreakStretch");	static CCryNameR streakParams0Name("StreakParams0");	static CCryNameR streakParams1Name("StreakParams1");	static CCryNameR streakParams2Name("StreakParams2");	CTexture* pStreakSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1];	CTexture* pStreakPingPong = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][0];	const float fTexelScaleX = 1.0f / (float)pStreakSource->GetWidth();	const float fTexelScaleY = 1.0f / (float)pStreakSource->GetHeight();	// The tone mapper blends the bloom target in with weight bloomAmount * 0.3 / 8 (about	// 0.004 at the default TOD bloom of 0.1). Anything added to the bloom target inherits	// that crush, so divide it back out - the streaks then keep the same on-screen energy	// regardless of the scene's bloom setting.	Vec4 vHDRSetupParams[5];	gEnv->p3DEngine->GetHDRSetupParams(vHDRSetupParams);	const float fBloomCompositeWeight = clamp_tpl(vHDRSetupParams[1].x / 8.0f, 0.0005f, 1.0f);	if (bBlade)	{		// The Count param carries the SPIKE count (even by construction: N for even blade		// counts, 2N for odd). Each pass draws a symmetric line = two opposed spikes, so the		// lines span 180 degrees and there are half as many passes as spikes.		const int nLineCount = clamp_tpl(streakParams.nDirectionCount / 2, 2, kMaxStreakDirections);		// Threshold. The knee is a quarter of the threshold, wide enough to stop the sources		// popping in and out between frames but far too narrow to catch a merely bright sky.		if (m_passStreakThreshold.IsDirty())		{			m_passStreakThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			m_passStreakThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			m_passStreakThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);			m_passStreakThreshold.SetRenderTarget(0, pStreakSource);			m_passStreakThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);			m_passStreakThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);			m_passStreakThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		m_passStreakThreshold.BeginConstantUpdate();		m_passStreakThreshold.SetConstant(streakParams1Name, Vec4(streakParams.fThreshold, max(streakParams.fThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);		m_passStreakThreshold.Execute();		// Directional stretch. The rays are evenly spread over the full circle and rotate with		// the blade phase; each one is grown by a chain of exponentially widening blurs.		// Perceived spike length is governed by how slowly the tail decays, not just by the		// sampling reach: short stubby spikes at length 0 (decay 0.55 per tap) grow into long		// persistent tails at length 1 (decay 0.95), while the stride widens the footprint.		const float fBaseStride = 0.5f + 2.0f * streakParams.fLength;		const float fLengthDecay = 0.55f + 0.40f * clamp_tpl(streakParams.fLength, 0.0f, 1.0f);		const float fOutputScale = streakParams.fAmount / ((float)nLineCount * fBloomCompositeWeight);		for (int direction = 0; direction < nLineCount; ++direction)		{			const float fAngle = streakParams.fAngle + (float)direction * (PI / (float)nLineCount);			const float fDirX = cosf(fAngle);			const float fDirY = sinf(fAngle);			float fStride = fBaseStride;			float fDecay = fLengthDecay;			for (int iteration = 0; iteration < kStreakIterations; ++iteration)			{				const bool bLastIteration = (iteration == kStreakIterations - 1);				CFullscreenPass& pass = m_passStreakStretch[direction][iteration];				if (pass.IsDirty())				{					const uint64 nBlendState = bLastIteration ? (GS_BLSRC_ONE | GS_BLDST_ONE) : 0;					pass.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);					pass.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);					pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);					pass.SetRenderTarget(0, bLastIteration ? m_graphicsPipelineResources.m_pTexHDRFinalBloom : pStreakPingPong);					pass.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | nBlendState);					pass.SetTexture(0, (iteration == 0) ? pStreakSource : pStreakPingPong);					pass.SetSampler(0, EDefaultSamplerStates::LinearClamp);				}				pass.BeginConstantUpdate();				pass.SetConstant(streakParams0Name, Vec4(fDirX * fTexelScaleX, fDirY * fTexelScaleY, fStride, bLastIteration ? fOutputScale : 1.0f), eHWSC_Pixel);				pass.SetConstant(streakParams1Name, Vec4(0, 0, fDecay, 0), eHWSC_Pixel);				// Untinted: the diffraction spikes keep the source's own colour.				pass.SetConstant(streakParams2Name, Vec4(1.0f, 1.0f, 1.0f, 0.0f), eHWSC_Pixel);				pass.Execute();				fStride *= (float)s_nStreakTapCount;				fDecay = powf(fDecay, (float)s_nStreakTapCount);			}		}	}	// Anamorphic horizontal flare. A cylindrical front element throws one long tinted line	// across the frame instead of a star, so this is a single horizontal march - but a much	// longer one: three iterations of 8 taps span 8^3 tap distances, the whole frame width.	if (bAnamorphic)	{		PROFILE_LABEL_SCOPE("ANAMORPHIC_FLARE");		// Own threshold pass into pStreakSource. The blade pass, if it ran at all, has already		// consumed its own thresholded copy, so the scratch target is free to be rewritten.		if (m_passAnamorphicThreshold.IsDirty())		{			m_passAnamorphicThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);			m_passAnamorphicThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);			m_passAnamorphicThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);			m_passAnamorphicThreshold.SetRenderTarget(0, pStreakSource);			m_passAnamorphicThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);			m_passAnamorphicThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);			m_passAnamorphicThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);		}		m_passAnamorphicThreshold.BeginConstantUpdate();		m_passAnamorphicThreshold.SetConstant(streakParams1Name, Vec4(streakParams.fAnamorphicThreshold, max(streakParams.fAnamorphicThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);		m_passAnamorphicThreshold.Execute();		const float fFlareLength = clamp_tpl(streakParams.fAnamorphicLength, 0.0f, 1.0f);		float fStride = 1.0f + 3.0f * fFlareLength;		float fDecay = 0.60f + 0.38f * fFlareLength;		const float fFlareScale = streakParams.fAnamorphicAmount / fBloomCompositeWeight;		const Vec4 vTint(streakParams.vAnamorphicTint.x, streakParams.vAnamorphicTint.y, streakParams.vAnamorphicTint.z, 0.0f);		for (int iteration = 0; iteration < kAnamorphicIterations; ++iteration)		{			const bool bLastIteration = (iteration == kAnamorphicIterations - 1);			CFullscreenPass& pass = m_passAnamorphicStretch[iteration];			// Three iterations need a real ping-pong: source -> pingpong -> source -> bloom.			// Reading and writing the same scratch target in one pass is undefined.			CTexture* pIterSource = (iteration % 2 == 0) ? pStreakSource : pStreakPingPong;			CTexture* pIterTarget = bLastIteration ? m_graphicsPipelineResources.m_pTexHDRFinalBloom			                                       : ((iteration % 2 == 0) ? pStreakPingPong : pStreakSource);			if (pass.IsDirty())			{				const uint64 nBlendState = bLastIteration ? (GS_BLSRC_ONE | GS_BLDST_ONE) : 0;				pass.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);				pass.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);				pass.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);				pass.SetRenderTarget(0, pIterTarget);				pass.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | nBlendState);				pass.SetTexture(0, pIterSource);				pass.SetSampler(0, EDefaultSamplerStates::LinearClamp);			}			pass.BeginConstantUpdate();			pass.SetConstant(streakParams0Name, Vec4(fTexelScaleX, 0.0f, fStride, bLastIteration ? fFlareScale : 1.0f), eHWSC_Pixel);			pass.SetConstant(streakParams1Name, Vec4(0, 0, fDecay, 0), eHWSC_Pixel);			// The coating's colour is applied once, on the pass that reaches the bloom target.			pass.SetConstant(streakParams2Name, bLastIteration ? vTint : Vec4(1.0f, 1.0f, 1.0f, 0.0f), eHWSC_Pixel);			pass.Execute();			fStride *= (float)s_nStreakTapCount;			fDecay = powf(fDecay, (float)s_nStreakTapCount);		}	}}// Front filter point spread function (FilterPSFSpec.md).//// A cross-screen / star filter is a plate of etched grooves mounted in FRONT of the lens, so// every bright point in the frame is diffracted into the same fixed pattern - lines// perpendicular to the grooves, at whatever angle the plate is turned to, with rainbow// dispersion toward their ends. Brighter sources show LONGER lines not because the pattern// changes but because more of its faint tail rises above the scene, which is exactly what// falls out of a convolution: the picture is the scene convolved with one fixed PSF.//// The convolution is done sparsely - one textured sprite per bright quarter-resolution texel,// deposited additively into the bloom target - so the cost follows the number of bright// sources rather than the frame area. The PSF is an authored RGB texture (like the bokeh// shape mask), which is what makes the same pass cover any other front-element PSF a preset// may want; a procedural N-point star stands in when nothing is bound.//// Runs after ExecuteStreaks, in the window where both quarter resolution scratch targets are// free again (the same one ExecuteHalation uses). Nothing here follows the f-number and// nothing is turned by the iris phase: a plate is not the aperture.void CBloomStage::ExecuteFilterPSF(){	// r_HDRStreaks is the master switch for the whole streak / flare / PSF block. Its	// diagnostic force mode (2) deliberately does NOT force the filter on: the plate is a	// separate piece of kit from the iris, and forcing it would hide whether the params	// arrive at all.	if (!CRenderer::CV_r_HDRStreaks)		return;	CHDRStreaks* pStreaksTech = static_cast<CHDRStreaks*>(PostEffectMgr()->GetEffect(EPostEffectID::HDRStreaks));	if (pStreaksTech == nullptr)		return;	const SHDRStreaksParams streakParams = pStreaksTech->GetParams();	// Amount 0 is off, and off means no pass at all - not a pass depositing zero.	if (streakParams.fFilterAmount < 0.001f)		return;	CTexture* pFilterSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1];	CTexture* pTarget = m_graphicsPipelineResources.m_pTexHDRFinalBloom;	if (!CTexture::IsTextureExist(pFilterSource) || !CTexture::IsTextureExist(pTarget))		return;	PROFILE_LABEL_SCOPE("HDR_FILTER_PSF");	static CCryNameTSCRC techStreakThreshold("HDRStreakThreshold");	static CCryNameTSCRC techFilterPSF("HDRFilterPSF");	static CCryNameR streakParams1Name("StreakParams1");	static CCryNameR filterParams0Name("FilterPSFParams0");	static CCryNameR filterParams1Name("FilterPSFParams1");	// 1. Threshold into the scratch target, the streaks' own technique and the same quarter	//    of the threshold as a soft knee - wide enough to stop sources popping between	//    frames, far too narrow to catch a merely bright sky.	if (m_passFilterThreshold.IsDirty())	{		m_passFilterThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passFilterThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passFilterThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);		m_passFilterThreshold.SetRenderTarget(0, pFilterSource);		m_passFilterThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_passFilterThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);		m_passFilterThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);	}	m_passFilterThreshold.BeginConstantUpdate();	m_passFilterThreshold.SetConstant(streakParams1Name, Vec4(streakParams.fFilterThreshold, max(streakParams.fFilterThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);	m_passFilterThreshold.Execute();	// 2. One sprite per source texel. The grid IS the thresholded target, so a cell and a	//    texel are the same thing and the vertex shader needs a single point read per quad.	const int32 nGridWidth = pFilterSource->GetWidth();	const int32 nGridHeight = pFilterSource->GetHeight();	const uint32 nVertexCount = uint32(nGridWidth) * uint32(nGridHeight) * 3 * 2;	if (!m_pFilterPSFPerViewCB)	{		m_pFilterPSFPerViewCB = gcpRendD3D->m_DevBufMan.CreateConstantBuffer(sizeof(HLSL_PerViewGlobalConstantBuffer));		if (m_pFilterPSFPerViewCB)			m_pFilterPSFPerViewCB->SetDebugName("FilterPSF Per-View CB");	}	if (!m_pFilterPSFPerViewCB)		return;	// The plate sits in FRONT of the anamorphic element, so its pattern is squeezed	// horizontally along with everything else in the frame. Read from the depth of field's	// user param, which is where the squeeze is authored - one knob, not two that can drift.	const float fSqueeze = clamp_tpl(PostEffectMgr()->GetByNameF("Dof_User_AnamorphicSqueeze"), 1.0f, 2.0f);	// Sprite half size. Size is a fraction of the frame HEIGHT so the reach is the same at	// any aspect ratio; the horizontal extent is then divided by the squeeze. R is in	// quarter-resolution pixels, which is also the unit the energy normalisation uses.	const float fRadiusPixels = max(streakParams.fFilterSize * (float)nGridHeight, 1.0f);	const float fRadiusNdcY = 2.0f * fRadiusPixels / (float)nGridHeight;	const float fRadiusNdcX = 2.0f * (fRadiusPixels / fSqueeze) / (float)nGridWidth;	// Same bloom-weight divide as the streaks and the halation: the tone mapper blends the	// bloom target in with weight bloomAmount * 0.3 / 8, so anything added here inherits that	// crush and has to have it divided back out to keep a constant on-screen energy.	Vec4 vHDRSetupParams[5];	gEnv->p3DEngine->GetHDRSetupParams(vHDRSetupParams);	const float fBloomCompositeWeight = clamp_tpl(vHDRSetupParams[1].x / 8.0f, 0.0005f, 1.0f);	// Dividing by the sprite AREA is what makes this a convolution rather than a glow: a	// wider plate spreads the same energy further instead of getting brighter. kNorm puts	// amount 1 at "clearly visible spikes on a lamp" for a PSF whose bright core is a few	// texels across; amount then absorbs whatever an authored PSF's own integral turns out to	// be, exactly as the bokeh splat's gain absorbs a shape mask's transmittance.	const float kNorm = 400.0f;	const float fEnergy = streakParams.fFilterAmount * kNorm / (fRadiusPixels * fRadiusPixels * fBloomCompositeWeight);	// N/2 line directions, so an odd point count rounds DOWN to the even star the procedural	// pattern can actually draw.	const int nPoints = clamp_tpl(streakParams.nFilterPoints & ~1, 4, 8);	CTexture* pPSFTex = streakParams.pFilterPSFTex;	const bool bPSFTexValid = CTexture::IsTextureExist(pPSFTex);	// Black, not white: the deposit is additive and the fallback slot is never read when the	// procedural star is selected, so a stray sample can only ever add nothing.	if (!bPSFTexValid)		pPSFTex = CRendererResources::s_ptexBlack;	// Ground truth log, once per change: what the plate actually resolves to.	{		static float s_lastAmount = -1.0f, s_lastSize = -1.0f, s_lastRotation = -1.0f, s_lastThreshold = -1.0f;		static int   s_lastPoints = -1;		static CryFixedStringT<256> s_lastName;		const char* szPSFName = bPSFTexValid ? pPSFTex->GetName() : "procedural";		if (fabsf(streakParams.fFilterAmount - s_lastAmount) > 0.005f ||		    fabsf(streakParams.fFilterSize - s_lastSize) > 0.005f ||		    fabsf(streakParams.fFilterRotation - s_lastRotation) > 0.005f ||		    fabsf(streakParams.fFilterThreshold - s_lastThreshold) > 0.05f ||		    nPoints != s_lastPoints || s_lastName != szPSFName)		{			s_lastAmount = streakParams.fFilterAmount;			s_lastSize = streakParams.fFilterSize;			s_lastRotation = streakParams.fFilterRotation;			s_lastThreshold = streakParams.fFilterThreshold;			s_lastPoints = nPoints;			s_lastName = szPSFName;			CryLog("[BLOOM] filter psf amount=%.2f size=%.2f rot=%.0f thresh=%.1f tex=%s",			       streakParams.fFilterAmount, streakParams.fFilterSize,			       RAD2DEG(streakParams.fFilterRotation), streakParams.fFilterThreshold, szPSFName);		}	}	// The per-view constant buffer describes the quarter-resolution GRID, not the render	// target: the vertex shader walks the quad grid and reads the source through it. Target	// and grid happen to be the same size here, but keeping them separate is what lets the	// sprite geometry stay pure NDC - the same trick the DOF's splat and ghost passes use.	const SRenderViewInfo& viewInfo = m_graphicsPipeline.GetCurrentViewInfo(CCamera::eEye_Left);	const SRenderViewport customViewport(0, 0, nGridWidth, nGridHeight);	m_graphicsPipeline.GeneratePerViewConstantBuffer(&viewInfo, (int)m_graphicsPipeline.GetViewInfoCount(), m_pFilterPSFPerViewCB, &customViewport);	D3DViewPort viewport;	viewport.TopLeftX = 0.0f;	viewport.TopLeftY = 0.0f;	viewport.Width = (float)pTarget->GetWidth();	viewport.Height = (float)pTarget->GetHeight();	viewport.MinDepth = 0.0f;	viewport.MaxDepth = 1.0f;	m_passFilterPSF.SetRenderTarget(0, pTarget);	m_passFilterPSF.SetViewport(viewport);	m_passFilterPSF.BeginAddingPrimitives();	CRenderPrimitive& prim = m_filterPSFPrimitive;	prim.SetFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_VS | CRenderPrimitive::eFlags_ReflectShaderConstants_PS);	prim.SetTechnique(CShaderMan::s_shHDRPostProcess, techFilterPSF, 0);	// Additive into the bloom target, exactly as the last stretch iteration of the streaks is.	prim.SetRenderState(GS_NODEPTHTEST | GS_NOCOLMASK_A | GS_BLSRC_ONE | GS_BLDST_ONE);	prim.SetCullMode(eCULL_None);	// Procedural geometry: no vertex or index stream, six vertices per source texel.	prim.SetCustomVertexStream(~0u, EDefaultInputLayouts::Empty, 0);	prim.SetDrawInfo(eptTriangleList, 0, 0, nVertexCount);	// The thresholded source is read by the VERTEX shader only (one point read to place and	// colour the sprite); the PSF image is read by the pixel shader only.	prim.SetTexture(0, pFilterSource, EDefaultResourceViews::Default, EShaderStage_Vertex);	prim.SetTexture(1, pPSFTex, EDefaultResourceViews::Default, EShaderStage_Pixel);	prim.SetSampler(0, EDefaultSamplerStates::PointClamp, EShaderStage_Vertex);	prim.SetSampler(1, EDefaultSamplerStates::LinearClamp, EShaderStage_Pixel);	prim.SetInlineConstantBuffer(eConstantBufferShaderSlot_PerView, m_pFilterPSFPerViewCB, EShaderStage_Vertex | EShaderStage_Pixel);	if (prim.Compile(m_passFilterPSF) != CRenderPrimitive::eDirty_None)	{		static bool s_bWarned = false;		if (!s_bWarned)		{			s_bWarned = true;			CryLogAlways("[BLOOM] filter psf primitive failed to compile - pass skipped");		}		return;	}	const Vec4 vFilterParams0(fRadiusNdcX, fRadiusNdcY, cosf(streakParams.fFilterRotation), sinf(streakParams.fFilterRotation));	const Vec4 vFilterParams1(fEnergy, (float)nPoints, bPSFTexValid ? 1.0f : 0.0f, 0.0f);	auto& constantManager = prim.GetConstantManager();	constantManager.BeginNamedConstantUpdate();	// Vertex: how big the sprite is and how much energy it carries.	constantManager.SetNamedConstant(filterParams0Name, vFilterParams0, eHWSC_Vertex);	constantManager.SetNamedConstant(filterParams1Name, vFilterParams1, eHWSC_Vertex);	// Pixel: the plate's rotation and which pattern to draw.	constantManager.SetNamedConstant(filterParams0Name, vFilterParams0, eHWSC_Pixel);	constantManager.SetNamedConstant(filterParams1Name, vFilterParams1, eHWSC_Pixel);	constantManager.EndNamedConstantUpdate(&viewport, m_graphicsPipeline.GetCurrentRenderView());	m_passFilterPSF.AddPrimitive(&prim);	m_passFilterPSF.Execute();}// Film halation.//// Light from a source bright enough to overload the emulsion passes through it, reflects off// the film base and re-exposes the emulsion from behind. The red-sensitive layer sits deepest,// so the re-exposure reads red-orange; it is much wider than the core itself and its edge is// soft. Halation is a property of the FILM STOCK, not of the lens, so unlike the diffraction// streaks nothing here follows the f-number.//// Runs after ExecuteStreaks so the two quarter resolution HDR scratch targets are free again,// and blends into $HDRFinalBloom through the same bloom-weight compensation the streaks use.void CBloomStage::ExecuteHalation(){	if (!CRenderer::CV_r_HDRHalation)		return;	CHDRHalation* pHalationTech = static_cast<CHDRHalation*>(PostEffectMgr()->GetEffect(EPostEffectID::HDRHalation));	if (pHalationTech == nullptr)		return;	SHDRHalationParams halationParams = pHalationTech->GetParams();	// r_HDRHalation 2: diagnostic force mode - full strength, low threshold, wide halo,	// independent of any game code driving the params.	if (CRenderer::CV_r_HDRHalation == 2)	{		halationParams.fAmount = 1.0f;		halationParams.fThreshold = 0.5f;		halationParams.fRadius = 0.7f;	}	if (halationParams.fAmount < 0.001f)		return;	PROFILE_LABEL_SCOPE("HDR_HALATION");	static CCryNameTSCRC techStreakThreshold("HDRStreakThreshold");	static CCryNameTSCRC techStreakStretch("HDRStreakStretch");	static CCryNameR streakParams0Name("StreakParams0");	static CCryNameR streakParams1Name("StreakParams1");	static CCryNameR streakParams2Name("StreakParams2");	CTexture* pHalationSource = m_graphicsPipelineResources.m_pTexHDRTargetScaled[1][1];	// Same bloom-weight divide as the streaks: the tone mapper blends the bloom target in with	// weight bloomAmount * 0.3 / 8, so anything added here inherits that crush and has to have	// it divided back out to keep a constant on-screen energy.	Vec4 vHDRSetupParams[5];	gEnv->p3DEngine->GetHDRSetupParams(vHDRSetupParams);	const float fBloomCompositeWeight = clamp_tpl(vHDRSetupParams[1].x / 8.0f, 0.0005f, 1.0f);	const float fRadius01 = clamp_tpl(halationParams.fRadius, 0.0f, 1.0f);	// 1. Threshold into the scratch target. Same soft knee (a quarter of the threshold) as the	//    streaks: wide enough to stop sources popping between frames, far too narrow to catch	//    a merely bright sky - which is exactly the point, a sky must not halate.	if (m_passHalationThreshold.IsDirty())	{		m_passHalationThreshold.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passHalationThreshold.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passHalationThreshold.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakThreshold, 0);		m_passHalationThreshold.SetRenderTarget(0, pHalationSource);		m_passHalationThreshold.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A);		m_passHalationThreshold.SetTexture(0, m_graphicsPipelineResources.m_pTexHDRTargetScaled[0][0]);		m_passHalationThreshold.SetSampler(0, EDefaultSamplerStates::LinearClamp);	}	m_passHalationThreshold.BeginConstantUpdate();	m_passHalationThreshold.SetConstant(streakParams1Name, Vec4(halationParams.fThreshold, max(halationParams.fThreshold * 0.25f, 0.01f), 0, 0), eHWSC_Pixel);	m_passHalationThreshold.Execute();	// 2. Take the thresholded source down to 1/16 resolution in two bilinear halvings (each one	//    averages a 2x2 block, so a small source keeps its energy instead of aliasing away).	//    The halo's WIDTH comes from the resolution the blur runs at, not from a tap stride:	//    CGaussianBlurPass has a fixed +-8 texel footprint, which at 1/16 resolution is +-128	//    full-res pixels. And it is a true separable Gaussian, so the result is ISOTROPIC - a	//    round halo. The earlier separable exponential spread was not: two 1D geometric	//    falloffs multiply into |x|+|y| isolines, a diamond/square halo emulsion scatter never	//    shows (verified square on screen by the user).	if (!AcquireHalationTargets(pHalationSource->GetWidth(), pHalationSource->GetHeight()))		return;	m_passHalationDown0.Execute(pHalationSource, m_pTexHalationEighth);	m_passHalationDown1.Execute(m_pTexHalationEighth, m_pTexHalationLow);	// 3. Isotropic Gaussian at 1/16 resolution. The distribution is the Gaussian's rho in	//    1/16-res texels (16 full-res pixels each on a 1080p frame): 2 -> 8 across the radius	//    range is a per-pass sigma of 32 -> 128 pixels, two passes about 1.4x that - radius	//    0.5 lands near 110 px (roughly four times the bloom core), radius 1 near 180 px.	const float fDistribution = 2.0f + 6.0f * fRadius01;	for (int iteration = 0; iteration < kHalationBlurIterations; ++iteration)		m_passHalationBlur.Execute(m_pTexHalationLow, m_pTexHalationLowTemp, 1.0f, fDistribution, false);	// 4. Composite into the bloom target. The stretch shader is reused with a ZERO step, so all	//    15 taps land on the same texel and the normalised sum is a plain tinted sample.	//	//    The energy conserving blur spreads a source over thousands of texels, which leaves the	//    halo far dimmer per pixel than the core it came from - correct as physics, invisible in	//    practice. The gain below puts it back at the strength an overloaded frame really shows,	//    so amount 1 is an obvious red-orange glow rather than a hint of one.	const float fHalationGain = 8.0f;	const float fOutputScale = halationParams.fAmount * fHalationGain / fBloomCompositeWeight;	const Vec4 vTint(halationParams.vTint.x, halationParams.vTint.y, halationParams.vTint.z, 0.0f);	// The 1/16-res result is read through a bilinear sampler, which is all the upsampling a	// halo this soft needs. The texture id is part of the dirty check: the low-res targets are	// re-created on a resolution change.	if (m_passHalationComposite.IsDirty(m_pTexHalationLow->GetTextureID()))	{		m_passHalationComposite.SetPrimitiveFlags(CRenderPrimitive::eFlags_ReflectShaderConstants_PS);		m_passHalationComposite.SetPrimitiveType(CRenderPrimitive::ePrim_ProceduralTriangle);		m_passHalationComposite.SetTechnique(CShaderMan::s_shHDRPostProcess, techStreakStretch, 0);		m_passHalationComposite.SetRenderTarget(0, m_graphicsPipelineResources.m_pTexHDRFinalBloom);		m_passHalationComposite.SetState(GS_NODEPTHTEST | GS_NOCOLMASK_A | GS_BLSRC_ONE | GS_BLDST_ONE);		m_passHalationComposite.SetTexture(0, m_pTexHalationLow);		m_passHalationComposite.SetSampler(0, EDefaultSamplerStates::LinearClamp);	}	m_passHalationComposite.BeginConstantUpdate();	m_passHalationComposite.SetConstant(streakParams0Name, Vec4(0.0f, 0.0f, 0.0f, fOutputScale), eHWSC_Pixel);	m_passHalationComposite.SetConstant(streakParams1Name, Vec4(0, 0, 1.0f, 0), eHWSC_Pixel);	m_passHalationComposite.SetConstant(streakParams2Name, vTint, eHWSC_Pixel);	m_passHalationComposite.Execute();}bool CBloomStage::AcquireHalationTargets(int quarterWidth, int quarterHeight){	const int w8  = max(quarterWidth / 2, 1);	const int h8  = max(quarterHeight / 2, 1);	const int w16 = max(quarterWidth / 4, 1);	const int h16 = max(quarterHeight / 4, 1);	if (m_pTexHalationEighth && m_pTexHalationLow && m_pTexHalationLowTemp &&	    m_halationLowWidth == w16 && m_halationLowHeight == h16)		return true;	ReleaseHalationTargets();	const uint32 flags = FT_NOMIPS | FT_DONT_STREAM | FT_USAGE_RENDERTARGET;	const std::string id = m_graphicsPipeline.GetUniqueIdentifierName();	m_pTexHalationEighth  = CTexture::GetOrCreateRenderTarget(("$HalationEighth" + id).c_str(),  w8,  h8,  Clr_Transparent, eTT_2D, flags, eTF_R16G16B16A16F);	m_pTexHalationLow     = CTexture::GetOrCreateRenderTarget(("$HalationLow" + id).c_str(),     w16, h16, Clr_Transparent, eTT_2D, flags, eTF_R16G16B16A16F);	m_pTexHalationLowTemp = CTexture::GetOrCreateRenderTarget(("$HalationLowTemp" + id).c_str(), w16, h16, Clr_Transparent, eTT_2D, flags, eTF_R16G16B16A16F);	if (!CTexture::IsTextureExist(m_pTexHalationEighth) || !CTexture::IsTextureExist(m_pTexHalationLow) || !CTexture::IsTextureExist(m_pTexHalationLowTemp))	{		ReleaseHalationTargets();		return false;	}	m_halationLowWidth = w16;	m_halationLowHeight = h16;	return true;}void CBloomStage::ReleaseHalationTargets(){	m_pTexHalationEighth.reset();	m_pTexHalationLow.reset();	m_pTexHalationLowTemp.reset();	m_halationLowWidth = 0;	m_halationLowHeight = 0;}